//! Differential testing of the zero-dimensional pipeline against an external computer algebra
//! system.
//!
//! M17 validated the conversion against 29 Singular reference bases, committed as literals and
//! regenerated by hand. That established the conventions but left the oracle out of the
//! development loop: it could not be pointed at a thousand random systems, and it compared only
//! the final lex basis — so a wrong multiplication-operator column could only be found if it
//! happened to change the answer.
//!
//! This module makes the oracle a tool. It generates deterministic systems, asks Singular about
//! each one, and compares **every intermediate result**: the source Gröbner basis, the quotient
//! dimension, the standard monomials, the normal form of each border monomial, each
//! multiplication-operator column, and the lex basis. Each of those has a precise mathematical
//! answer, which is what makes it a unit worth comparing rather than an internal detail.
//!
//! ```text
//! cargo run --release --bin zeebra-differential -- --systems 500
//! ```
//!
//! # CI does not need Singular
//! A sweep's agreeing cases can be emitted as [`DifferentialFixture`] literals and committed. An
//! ordinary Rust test then replays the same comparison against the recorded answers, so the checks
//! CI runs are the checks the development machine runs — with a table of constants where the
//! subprocess was. See [`fixture`].
//!
//! # An oracle that did not answer is not agreement
//! Singular exits 0 after a script error. A timeout, a missing binary, a characteristic outside
//! Singular's range, or an answer Singular contradicts itself on each produce an
//! [`OracleError`](singular::OracleError), which [`SweepReport::clean`](sweep::SweepReport::clean)
//! counts as a failure of the sweep.

pub mod check;
pub mod comparison;
pub mod fixture;
pub mod generator;
pub mod singular;
pub mod sweep;
pub mod text;

/// Oracle answers recorded from Singular. Test-only: it is reference data, not library code.
#[cfg(test)]
mod fixtures;

pub use check::{check_generated, check_system, verify_recorded, SystemOutcome};
pub use comparison::{
    verify_case, Agreement, Check, DifferentialCase, Disagreement, SOURCE_ORDER, TARGET_ORDER,
};
pub use fixture::{emit_failure, emit_fixture, emit_fixture_module, DifferentialFixture};
pub use generator::{GeneratedSystem, GeneratedTerm, SystemShape};
pub use singular::{Oracle, OracleError, OracleQuery, SingularOracle, MAX_CHARACTERISTIC};
pub use sweep::{run_sweep, Failure, SweepOptions, SweepReport};
pub use text::{monomial_to_string, polynomial_to_string};

#[cfg(test)]
mod tests {
    use std::collections::HashSet;

    use super::{
        check::{check_generated, verify_recorded, SUPPORTED_CHARACTERISTICS, SUPPORTED_VARIABLES},
        comparison::{verify_case, Check, DifferentialCase},
        fixtures::FIXTURES,
        generator::{GeneratedSystem, SystemShape},
        singular::{Oracle, OracleError, OracleQuery},
        SystemOutcome,
    };
    use crate::{
        fields::{Zp13, Zp7},
        grobner::fglm::{FglmOptions, OperatorConstruction, OperatorStorage},
    };

    /// An oracle that answers from a recorded table and refuses anything else.
    ///
    /// Lets `check_system` — the live harness's own code path — be exercised in CI with no
    /// subprocess. A query it has no answer for is an error and never a silent pass.
    struct RecordedOracle {
        cases: Vec<DifferentialCase>,
    }

    impl Oracle for RecordedOracle {
        fn interrogate(
            &mut self,
            query: &OracleQuery<'_>,
        ) -> Result<DifferentialCase, OracleError> {
            self.cases
                .iter()
                .find(|case| case.name == query.name)
                .cloned()
                .ok_or(OracleError::Incomplete)
        }
    }

    /// Every committed fixture agrees with Zeebra, with no oracle present.
    #[test]
    fn test_every_committed_fixture_agrees() {
        assert!(!FIXTURES.is_empty(), "the fixture table is empty");

        for fixture in FIXTURES {
            let case = fixture.to_case();
            match verify_recorded(&case, &FglmOptions::unbounded()) {
                Ok(_) => {}
                Err(disagreement) => panic!("{}: {}", fixture.name, disagreement),
            }
        }
    }

    /// Every committed fixture agrees under every operator-construction strategy.
    ///
    /// The strategies are asserted equal to each other in `quotient_algebra.rs`; this asserts each
    /// separately equal to *Singular*, over 240 ideals and six fields. Two implementations agreeing
    /// with each other and both being wrong is the thing an external oracle is for.
    #[test]
    fn test_every_fixture_agrees_under_every_strategy() {
        for construction in [
            OperatorConstruction::PerColumn,
            OperatorConstruction::DeduplicatedBorder,
            OperatorConstruction::BatchedBorder,
        ] {
            for storage in [
                OperatorStorage::Sparse,
                OperatorStorage::Adaptive,
                OperatorStorage::Dense,
            ] {
                let options = FglmOptions::unbounded()
                    .with_operator_construction(construction)
                    .with_operator_storage(storage);
                for fixture in FIXTURES {
                    if let Err(disagreement) = verify_recorded(&fixture.to_case(), &options) {
                        panic!(
                            "{} under {:?} and {:?}: {}",
                            fixture.name, construction, storage, disagreement
                        );
                    }
                }
            }
        }
    }

    /// The shape-form route ran, and agreed, on a substantial share of the fixtures.
    ///
    /// `verify_recorded` skips the shape check where the ideal is not in shape position, which is a
    /// correct answer — so without this the check could be skipped on all 240 cases and the suite
    /// would still be green. This asserts it was exercised against Singular, and reports what
    /// fraction of the corpus the prototype covers.
    #[test]
    fn test_the_shape_route_agrees_where_it_applies() {
        let options = FglmOptions::unbounded();
        let mut zero_dimensional = 0;
        let mut in_shape_position = 0;

        for fixture in FIXTURES {
            let case = fixture.to_case();
            let agreement = verify_recorded(&case, &options)
                .unwrap_or_else(|disagreement| panic!("{}: {}", fixture.name, disagreement));

            if matches!(agreement.quotient_dimension, Some(d) if d > 0) {
                zero_dimensional += 1;
                if agreement.shape_basis_agreed == Some(true) {
                    in_shape_position += 1;
                }
            }
        }

        assert!(zero_dimensional > 0, "no fixture has a nonzero quotient");
        assert!(
            in_shape_position * 2 >= zero_dimensional,
            "the shape route ran on only {} of {} zero-dimensional fixtures, which is too few to \
             be evidence",
            in_shape_position,
            zero_dimensional
        );
    }

    /// The fixtures cover every characteristic and variable count the harness supports.
    ///
    /// A table that happened to hold only large-prime two-variable cases would pass the test above
    /// while checking almost nothing, which is the failure this prevents.
    #[test]
    fn test_the_fixtures_cover_every_field_and_variable_count() {
        let characteristics: HashSet<u64> = FIXTURES.iter().map(|f| f.characteristic).collect();
        let variables: HashSet<usize> = FIXTURES.iter().map(|f| f.variables.len()).collect();

        for characteristic in SUPPORTED_CHARACTERISTICS {
            assert!(
                characteristics.contains(characteristic),
                "no fixture over GF({})",
                characteristic
            );
        }
        for count in SUPPORTED_VARIABLES {
            assert!(
                variables.contains(count),
                "no fixture in {} variables",
                count
            );
        }
    }

    /// The fixtures cover the three outcomes, not only the easy one.
    ///
    /// A zero-dimensional ideal with a nonzero quotient, the unit ideal, and a
    /// positive-dimensional ideal that both sides must reject.
    #[test]
    fn test_the_fixtures_cover_every_ideal_class() {
        let zero_dimensional = FIXTURES
            .iter()
            .filter(|f| matches!(f.quotient_dimension, Some(d) if d > 0))
            .count();
        let unit = FIXTURES
            .iter()
            .filter(|f| f.quotient_dimension == Some(0))
            .count();
        let positive = FIXTURES
            .iter()
            .filter(|f| f.quotient_dimension.is_none())
            .count();

        assert!(zero_dimensional > 0, "no zero-dimensional fixture");
        assert!(unit > 0, "no unit-ideal fixture");
        assert!(positive > 0, "no positive-dimensional fixture");
    }

    /// Every zero-dimensional fixture records a normal form for every one of its border monomials.
    ///
    /// The operator-column check is only as strong as the border coverage, and `verify_case`
    /// enforces that — so this asserts the table is not merely passing by being asked nothing.
    #[test]
    fn test_the_fixtures_record_border_normal_forms() {
        let with_border = FIXTURES
            .iter()
            .filter(|f| !f.border_normal_forms.is_empty())
            .count();
        assert!(
            with_border > 0,
            "no fixture records a border normal form, so no operator column was checked"
        );

        for fixture in FIXTURES {
            if fixture.quotient_dimension.unwrap_or(0) == 0 {
                continue;
            }
            // Every standard monomial has at least one variable multiple, and not all of them can
            // stay standard — the basis is finite. So a zero-dimensional quotient with a nonzero
            // dimension always has a nonempty border.
            assert!(
                !fixture.border_normal_forms.is_empty(),
                "{} has dimension {:?} and an empty border",
                fixture.name,
                fixture.quotient_dimension
            );
        }
    }

    /// A corrupted fixture is detected, which is what makes a passing table evidence.
    ///
    /// Each perturbation targets a different check, so this also shows the checks are wired to the
    /// fields they are named after.
    #[test]
    fn test_a_corrupted_fixture_is_detected() {
        let original = FIXTURES
            .iter()
            .find(|f| matches!(f.quotient_dimension, Some(d) if d > 1))
            .expect("a zero-dimensional fixture of dimension above one")
            .to_case();

        // The dimension.
        let mut corrupted = original.clone();
        corrupted.quotient_dimension = Some(original.quotient_dimension.unwrap() + 1);
        assert_eq!(
            verify_recorded(&corrupted, &FglmOptions::unbounded())
                .unwrap_err()
                .check,
            Check::QuotientDimension
        );

        // The source basis.
        let mut corrupted = original.clone();
        corrupted.grevlex_basis.pop();
        assert_eq!(
            verify_recorded(&corrupted, &FglmOptions::unbounded())
                .unwrap_err()
                .check,
            Check::SourceBasis
        );

        // The standard monomials.
        let mut corrupted = original.clone();
        corrupted.standard_monomials[0] = "x1^99".to_string();
        assert_eq!(
            verify_recorded(&corrupted, &FglmOptions::unbounded())
                .unwrap_err()
                .check,
            Check::StandardMonomials
        );

        // The border coverage.
        let mut corrupted = original.clone();
        corrupted.border_normal_forms.pop();
        assert_eq!(
            verify_recorded(&corrupted, &FglmOptions::unbounded())
                .unwrap_err()
                .check,
            Check::BorderCoverage
        );

        // A border normal form, which is also what an operator column is built from.
        let mut corrupted = original.clone();
        let (monomial, normal_form) = corrupted.border_normal_forms[0].clone();
        corrupted.border_normal_forms[0] = (monomial, format!("{}+1", normal_form));
        let check = verify_recorded(&corrupted, &FglmOptions::unbounded())
            .unwrap_err()
            .check;
        assert!(
            check == Check::BorderNormalForm || check == Check::OperatorColumn,
            "a corrupted normal form was reported as {:?}",
            check
        );

        // The lex basis.
        let mut corrupted = original.clone();
        corrupted.lex_basis = Some(vec!["x1".to_string()]);
        assert_eq!(
            verify_recorded(&corrupted, &FglmOptions::unbounded())
                .unwrap_err()
                .check,
            Check::LexBasis
        );

        // A missing lex basis is a gap in the case, not an agreement.
        let mut corrupted = original.clone();
        corrupted.lex_basis = None;
        assert_eq!(
            verify_recorded(&corrupted, &FglmOptions::unbounded())
                .unwrap_err()
                .check,
            Check::LexBasis
        );
    }

    /// A case over a field the harness does not instantiate is rejected rather than checked.
    #[test]
    fn test_a_case_over_an_uninstantiated_field_is_rejected() {
        let mut case = FIXTURES[0].to_case();
        case.characteristic = 11;
        assert_eq!(
            verify_recorded(&case, &FglmOptions::unbounded())
                .unwrap_err()
                .check,
            Check::Field
        );
    }

    /// Verifying a case at the wrong variable count or characteristic is rejected, not attempted.
    ///
    /// `verify_recorded` dispatches *from* the case's own variable count and characteristic, so it
    /// cannot reach this. It is reachable by calling the generic entry point directly, which is
    /// what a future caller with its own dispatch table would do — and a case checked in the wrong
    /// ring would otherwise agree or disagree for reasons that have nothing to do with the ideal.
    #[test]
    fn test_verifying_a_case_in_the_wrong_ring_is_rejected() {
        // Two variables, and over neither of the fields it is about to be checked over: a case
        // verified in a ring it *is* stated over would agree, which would make the assertions
        // below pass or fail on which fixture happened to come first in the table.
        let case = FIXTURES
            .iter()
            .find(|f| f.variables.len() == 2 && f.characteristic != 7 && f.characteristic != 13)
            .expect("a two-variable fixture over neither GF(7) nor GF(13)")
            .to_case();

        assert_eq!(
            verify_case::<3, Zp13>(&case, &FglmOptions::unbounded())
                .unwrap_err()
                .check,
            Check::Field,
            "a two-variable case was checked as a three-variable one"
        );
        assert_eq!(
            verify_case::<2, Zp7>(&case, &FglmOptions::unbounded())
                .unwrap_err()
                .check,
            Check::Field,
            "a case was checked over a field it is not stated over"
        );
    }

    /// The live harness's own path agrees when the oracle replays a committed fixture.
    ///
    /// `check_system` regenerates the system from its seed, computes Zeebra's border, queries the
    /// oracle, and verifies — exactly as it does against Singular. Here the oracle is a table, so
    /// the test needs no installation.
    #[test]
    fn test_the_harness_path_agrees_against_a_recorded_oracle() {
        let mut checked = 0;
        for fixture in FIXTURES {
            // Only fixtures still named after their seed can be regenerated; a minimized one
            // cannot, and is covered by the fixture test above instead.
            let Some(system) = system_of(fixture.name) else {
                continue;
            };
            if system.render() != fixture.system {
                continue;
            }

            let mut oracle = RecordedOracle {
                cases: vec![fixture.to_case()],
            };
            match check_generated(&system, &mut oracle, &FglmOptions::unbounded()) {
                SystemOutcome::Agreed { .. } => checked += 1,
                other => panic!("{}: {}", fixture.name, other.summary()),
            }
        }
        assert!(
            checked > 0,
            "no fixture could be regenerated from its name, so the harness path was not exercised"
        );
    }

    /// An oracle that cannot answer gives an oracle failure, never agreement.
    #[test]
    fn test_an_unanswering_oracle_is_not_agreement() {
        let system = GeneratedSystem::generate(
            1,
            SystemShape {
                variables: 2,
                max_degree: 2,
                max_terms: 3,
            },
            13,
        );
        let mut oracle = RecordedOracle { cases: Vec::new() };
        let outcome = check_generated(&system, &mut oracle, &FglmOptions::unbounded());
        assert!(!outcome.agreed(), "{}", outcome.summary());
        assert!(matches!(outcome, SystemOutcome::OracleFailed { .. }));
    }

    /// A shape the harness does not instantiate is reported as skipped, not as agreement.
    #[test]
    fn test_an_unsupported_shape_is_reported() {
        let system = GeneratedSystem::generate(
            1,
            SystemShape {
                variables: 7,
                max_degree: 2,
                max_terms: 3,
            },
            13,
        );
        let mut oracle = RecordedOracle { cases: Vec::new() };
        let outcome = check_generated(&system, &mut oracle, &FglmOptions::unbounded());
        assert!(!outcome.agreed());
        assert!(matches!(outcome, SystemOutcome::Unsupported { .. }));
    }

    /// A live sweep against a local Singular, which must be installed to run this.
    ///
    /// `#[ignore]`d: ordinary CI has no Singular, and a test that silently passed when the oracle
    /// is absent would be worse than no test. Run it with
    ///
    /// ```text
    /// cargo test --release --lib -- --ignored --exact \
    ///     grobner::differential::tests::test_a_live_sweep_against_singular_agrees
    /// ```
    ///
    /// The binary is the tool for a real sweep — this is the same thing at a size that belongs in
    /// a test, and it exists so that the live path is exercised by `cargo test` at all.
    #[test]
    #[ignore = "needs a local Singular installation"]
    fn test_a_live_sweep_against_singular_agrees() {
        use super::{run_sweep, SingularOracle, SweepOptions};
        use std::time::Duration;

        let work_dir =
            std::env::temp_dir().join(format!("zeebra-differential-test-{}", std::process::id()));
        let mut oracle = SingularOracle::new("Singular", &work_dir, Duration::from_secs(60), false)
            .expect("a writable scratch directory");
        let version = oracle.version().expect("Singular runs");

        let options = SweepOptions {
            seed: 90_000,
            systems: 24,
            variables: SUPPORTED_VARIABLES.to_vec(),
            characteristics: SUPPORTED_CHARACTERISTICS.to_vec(),
            max_degree: 3,
            max_terms: 4,
            minimize_attempts: 0,
            minimize_budget: Duration::from_secs(0),
            fglm: FglmOptions::unbounded(),
        };
        let report = run_sweep(&options, &mut oracle, &mut |_, _, _| {});

        assert!(
            report.clean(),
            "Singular build {}: {} disagreements, {} oracle failures {:?}, {} Zeebra failures {:?}",
            version,
            report.failures.len(),
            report.oracle_failures.len(),
            report.oracle_failures,
            report.zeebra_failures.len(),
            report.zeebra_failures,
        );
        assert_eq!(report.agreed, 24);
        assert!(
            report.zero_dimensional > 0,
            "the sweep found no zero-dimensional ideal, so it checked no operator column"
        );
        let _ = std::fs::remove_dir_all(&work_dir);
    }

    /// `seed-<n>-p<p>-n<v>` back to the system it names.
    fn system_of(name: &str) -> Option<GeneratedSystem> {
        let rest = name.strip_prefix("seed-")?;
        let (seed, rest) = rest.split_once("-p")?;
        let (characteristic, variables) = rest.split_once("-n")?;
        Some(GeneratedSystem::generate(
            seed.parse().ok()?,
            SystemShape {
                variables: variables.parse().ok()?,
                max_degree: DEFAULT_MAX_DEGREE,
                max_terms: DEFAULT_MAX_TERMS,
            },
            characteristic.parse().ok()?,
        ))
    }

    /// The shape the committed fixtures were generated at. Changing either invalidates the
    /// regeneration above, which is why `test_the_harness_path_agrees_against_a_recorded_oracle`
    /// asserts that at least one fixture could be reproduced.
    const DEFAULT_MAX_DEGREE: u32 = 4;
    const DEFAULT_MAX_TERMS: usize = 5;
}
